const next = { ...$json };
const chatInput =
  typeof next.chatInput === 'string'
    ? next.chatInput
    : typeof next.mensaje === 'string'
      ? next.mensaje
      : '';
const contextoFuente =
  next.contexto && typeof next.contexto === 'object'
    ? next.contexto
    : next.contexto_json || {};
const contexto =
  contextoFuente && typeof contextoFuente === 'object' ? contextoFuente : {};

if (!contexto.chatInput) {
  contexto.chatInput = chatInput;
}

next.contexto = contexto;
next.chatInput = chatInput;
next.mensaje = chatInput;
try {
  next.contextoTexto = next.contextoTexto || JSON.stringify(contexto, null, 2);
} catch (error) {
  next.contextoTexto = next.contextoTexto || '';
}

return [
  {
    json: next,
  },
];

