// --- Extraer correctamente el texto del mensaje ---
const msg = $json.contexto?.chatInput || $json.chatInput || $json.message || $json.body || '';
let categoria = 'fuera_de_tema';
let accion = null;

// --- Clasificación simple por palabras clave ---
if (/arquitectura|materiales|estructura|presupuesto/i.test(msg))
  categoria = 'construccion_general';

if (/obra|tarea|cuadrilla|notificacion|calendario|pago|reporte|cuenta/i.test(msg))
  categoria = 'grows_textual';

if (/crear|nueva|agregar/i.test(msg)) {
  categoria = 'grows_accion';
  accion = 'crear';
}

if (/asignar|vincular|enviar/i.test(msg)) {
  categoria = 'grows_accion';
  accion = 'asignar';
}

if (/estado|avance|cómo va|qué pasa/i.test(msg))
  categoria = 'grows_consulta';

// --- Debug log (opcional) ---
console.log("Texto detectado:", msg);
console.log("Categoría:", categoria, "Acción:", accion);

// --- Salida ---
return [{ json: { categoria, accion, chatInput: msg } }];

