=Sos GrowsBot, el asistente tecnico de la plataforma GROWS.
Responde en espanol con tono profesional y tecnico.
Usa el siguiente contexto:

{{ $json.contextoTexto ?? JSON.stringify($json.contexto, null, 2) }}

Usuario: {{ $json.chatInput }}

parameters.jsCode:
const fs = require('fs');

const candidates = [
  $json.chatInput,
  $json.chatinput,
  $json.message,
  $json.Message,
  $json.mensaje,
  $json.text,
  $json.body,
  $json.data?.message,
  $json.data?.chatInput,
  $json.contexto?.chatInput,
];

let rawMessage = '';
for (const value of candidates) {
  if (typeof value === 'string' && value.trim().length > 0) {
    rawMessage = value.trim();
    break;
  }
  if (value && typeof value === 'object') {
    rawMessage = JSON.stringify(value);
    break;
  }
}

const basePath = "C:\\Users\\Pc\\Desktop\\JOSE\\Programacion\\GROWS_SUSCRIPCIONES\\GROWS_COPIA\\contextos\\";
const mappings = [
  { keywords: ['obra', 'obras'], file: 'contexto_obras.json' },
  { keywords: ['tarea', 'tareas'], file: 'contexto_tareas.json' },
  { keywords: ['cuadrilla', 'cuadrillas'], file: 'contexto_cuadrillas.json' },
  { keywords: ['notificacion', 'notificaciones', 'alerta', 'alertas'], file: 'contexto_notificaciones.json' },
  { keywords: ['calendario', 'agenda', 'cronograma'], file: 'contexto_calendario.json' },
  { keywords: ['pago', 'pagos', 'facturacion'], file: 'contexto_pagos.json' },
  { keywords: ['reporte', 'reportes', 'kpi', 'indicador'], file: 'contexto_reportes.json' },
  { keywords: ['cuenta', 'perfil', 'suscripcion'], file: 'contexto_cuenta.json' },
  { keywords: ['rol', 'roles', 'permiso'], file: 'contexto_roles.json' },
  { keywords: ['plan', 'planes', 'upgrade'], file: 'contexto_planes.json' },
  { keywords: ['tecnologia', 'stack', 'arquitectura', 'infraestructura'], file: 'contexto_tecnologia.json' },
];

const normalize = (text) =>
  text.toString().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const normalizedMessage = rawMessage ? normalize(rawMessage) : '';
let selectedFile = 'contexto_roles.json';
let matchedKeywords = [];
for (const mapping of mappings) {
  if (mapping.keywords.some((keyword) => normalizedMessage.includes(keyword))) {
    selectedFile = mapping.file;
    matchedKeywords = mapping.keywords.filter((keyword) =>
      normalizedMessage.includes(keyword)
    );
    break;
  }
}

let warning = null;
const detected = matchedKeywords.length > 0;
let resolvedPath = `${basePath}${selectedFile}`;
if (!fs.existsSync(resolvedPath)) {
  warning = 'Contexto no encontrado. Se cargo el contexto por defecto: contexto_roles.json';
  selectedFile = 'contexto_roles.json';
  resolvedPath = `${basePath}${selectedFile}`;
}

if (!detected && warning === null) {
  warning = 'No se detectaron coincidencias. Se uso el contexto por defecto: contexto_roles.json';
}

const next = { ...$json };
next.chatInput = rawMessage;
next.mensaje = rawMessage;
next.contexto_file = selectedFile;
next.contexto_path = resolvedPath;
next.contexto_basePath = basePath;
next.contexto_keywords = matchedKeywords;
next.contexto_detectado = detected;
next.contexto_warning = warning;

return [
  {
    json: next,
  },
];

const next = { ...$json };
const contextoFuente = next.contexto_json ?? next.contexto ?? {};
const contexto =
  contextoFuente && typeof contextoFuente === 'object' ? contextoFuente : {};
const resumen =
  typeof contexto.contexto_resumido === 'string'
    ? contexto.contexto_resumido
    : contexto.descripcion || contexto.descripcion_general || '';

next.contexto = contexto;
try {
  next.contextoTexto = next.contextoTexto || JSON.stringify(contexto, null, 2);
} catch (error) {
  next.contextoTexto = next.contextoTexto || '';
}
next.contexto_resumen = resumen;
const resumenLineas = resumen
  ? resumen
      .split('\n')
      .map((line) => line.trim())
      .filter((line) => line.length)
  : [];
const resumenCorto = resumenLineas.slice(0, 2).join(' ');
next.verificacion_contexto = `Archivo: ${next.contexto_file} | Resumen: ${
  resumenCorto || 'sin resumen'
}`;
if (next.contexto_warning) {
  next.verificacion_contexto += ` | Aviso: ${next.contexto_warning}`;
}

return [
  {
    json: next,
  },
];
